$('#loadPanel').insertAdjacentHTML('afterend','<div id="rtWorkExtras" class="hidden"><label class="rt-check"><input id="rtLiveFailure" type="checkbox">Registrar repeticiones realizadas</label><label id="rtActualLabel" class="hidden">¿Cuántas hiciste?<input id="rtActualReps" type="number" min="0" max="1000" step="1" placeholder="Repeticiones de esta serie"></label></div><div id="rtRestExtras" class="rt-row hidden"><button id="rtRest10" class="rt-small">+10 s</button><button id="rtRest20" class="rt-small">+20 s</button><button id="rtRest60" class="rt-small">+1 min</button></div>');
for(const n of [10,20,60])$('#rtRest'+n).onclick=()=>{if(plan[idx]?.type!=='rest')return;remaining+=n;total+=n;update();saveWorkoutState()};
$('#rtLiveFailure').onchange=()=>{const p=plan[idx];if(p?.type!=='work')return;captureCurrentSet();p.failure=$('#rtLiveFailure').checked;if(p.failure){p.mode='reps';stop(false)}renderCurrentStep(false);saveWorkoutState()};$('#rtActualReps').oninput=()=>{captureCurrentSet();saveWorkoutState()};
captureCurrentSet=function(){const p=plan[idx];if(!p||p.type!=='work')return;const raw=$('#exerciseLoad').value,actual=$('#rtActualReps').value;setLogs[idx]={name:p.name,exerciseId:p.exerciseId,side:p.side||'',dropIndex:p.dropIndex??null,set:Number(p.set)||1,reps:p.mode==='reps'?(p.failure?(actual===''?null:Math.max(0,Number(actual)||0)):Number(p.amount)||0):0,kg:raw===''?0:Math.max(0,rtKg(raw)||0),mode:p.mode,amount:Number(p.amount)||0,failure:!!p.failure,completed:!!setLogs[idx]?.completed}};
renderCurrentStep=function(auto=false){const p=plan[idx];if(!p)return;const work=p.type==='work';$('#trainRoutineName').textContent=($('#routineName').value||'Rutina')+(trainingDayName?' · '+trainingDayName:'');$('#phase').textContent=work?'EJERCICIO':'DESCANSO';$('#exercise').textContent=p.name+(p.side?' · '+p.side:'')+(p.dropIndex!=null?' · Etapa '+(p.dropIndex+1):'');$('#round').textContent='Serie '+(p.set||p.round||1);$('#step').textContent=(idx+1)+' / '+plan.length;$('#next').textContent=plan[idx+1]?.name||'Fin';$('#complete').classList.toggle('hidden',!(work&&p.mode==='reps'));$('#loadPanel').classList.toggle('hidden',!work);$('#rtWorkExtras').classList.toggle('hidden',!work);$('#rtRestExtras').classList.toggle('hidden',work);if(work){$('#exerciseLoad').value=setLogs[idx]?.kg!==undefined?rtMass(setLogs[idx].kg):p.plannedKg!==undefined?rtMass(p.plannedKg):suggestedLoad(p.name)!==''?rtMass(suggestedLoad(p.name)):'';$('#rtLiveFailure').checked=!!p.failure;$('#rtActualLabel').classList.toggle('hidden',!p.failure);$('#rtActualReps').value=setLogs[idx]?.reps??''}$('#sub').textContent=work?'Serie '+(p.set||1)+' de '+p.sets:'Recuperación';rtUnitLabels();update();if(work&&p.mode==='reps'){$('#timer').textContent=p.failure?'REPS':p.amount;$('#play').textContent='—'}else if(auto)countdown();else $('#play').textContent='Continuar';if(auto)rtSpeak(work?p.name+(p.side?', lado '+p.side:''):'Descanso. Próximo ejercicio: '+(plan.slice(idx+1).find(x=>x.type==='work')?.name||'fin'));updateMediaSession()};
