const oldPrep=prep;prep=function(){rtSpeak('Preparate. '+(plan[0]?.name||''));oldPrep()};
const oldLoadStep=loadStep;loadStep=function(i){const p=plan[idx];if(i>idx&&p?.type==='work'){if(p.failure&&($('#rtActualReps').value===''||!Number.isInteger(Number($('#rtActualReps').value))||Number($('#rtActualReps').value)<0||Number($('#rtActualReps').value)>1000)){stop(false);$('#rtActualReps').focus();return rtToast('Anotá cuántas repeticiones hiciste; podés poner 0.')}captureCurrentSet();setLogs[idx].completed=true}oldLoadStep(i);if(idx>=plan.length){$('#rtWorkExtras').classList.add('hidden');$('#rtRestExtras').classList.add('hidden');$('#timer').classList.add('rt-gold','rt-celebrate');rtSpeak('Entrenamiento completado')}else $('#timer').classList.remove('rt-gold','rt-celebrate')};
const oldIdle=idle;idle=function(){oldIdle();$('#rtWorkExtras').classList.add('hidden');$('#rtRestExtras').classList.add('hidden')};
const oldSaveState=saveWorkoutState;saveWorkoutState=function(){oldSaveState();if(currentUser&&idx>=0&&idx<plan.length)rtWrite('workoutContext',{routineId:RT.sessionRoutine,dayIndex:RT.sessionDay})};
const oldRestore=restoreWorkout;restoreWorkout=function(){const c=rtRead('workoutContext',{});RT.sessionRoutine=c.routineId||null;RT.sessionDay=c.dayIndex||0;return oldRestore()};
recordWorkout=function(){if(!currentUser||workoutRecorded||!workoutStartedAt)return;workoutRecorded=true;const logs=Object.values(setLogs).filter(x=>x?.completed),past=rtRead('records',{}),records=[];for(const h of workoutHistory)for(const l of h.setLogs||[]){const k=l.name+'|'+(l.side||'')+'|'+l.mode;const old=past[k]||{kg:0,reps:0};if(l.kg>old.kg)past[k]={kg:l.kg,reps:l.reps||0};else if(l.kg===old.kg)past[k]={kg:old.kg,reps:Math.max(old.reps,l.reps||0)}}for(const l of logs){const key=l.name+'|'+(l.side||'')+'|'+l.mode,previous=past[key];if(previous&&l.kg>previous.kg)records.push(l.name+': '+rtMassText(l.kg));past[key]=!previous||l.kg>previous.kg?{kg:l.kg,reps:l.reps||0}:l.kg===previous.kg?{kg:l.kg,reps:Math.max(previous.reps,l.reps||0)}:previous;if(previous&&l.kg===previous.kg&&(l.reps||0)>previous.reps)records.push(l.name+': '+l.reps+' reps')}rtWrite('records',past);const entry={id:crypto.randomUUID(),name:$('#routineName').value||'Rutina',routineId:RT.sessionRoutine,dayIndex:RT.sessionDay,dayName:trainingDayName,programSignature:RT.sessionRoutine&&savedRoutines.find(r=>r.id===RT.sessionRoutine)?JSON.stringify(RTCore.routine(savedRoutines.find(r=>r.id===RT.sessionRoutine))):null,localDay:localDate(),finishedAt:new Date().toISOString(),durationSec:Math.max(1,Math.round((Date.now()-workoutStartedAt)/1000)),exerciseCount:new Set(logs.map(x=>x.exerciseId??x.name)).size,totalSets:new Set(logs.map(x=>(x.exerciseId??x.name)+':'+x.set)).size,totalReps:logs.reduce((n,x)=>n+(x.reps||0),0),totalVolume:logs.filter(x=>x.mode==='reps').reduce((n,x)=>n+x.kg*(x.reps||0),0),setLogs:logs,records};loadWorkoutHistory();workoutHistory.unshift(entry);localStorage.setItem(historyKey(),JSON.stringify(workoutHistory));renderWorkoutHistory();rtToast(records.length?'Nuevo récord · '+records.slice(0,3).join(' · '):'¡Entrenamiento completado! Sesión guardada.',true)};
const oldHistoryRender=renderWorkoutHistory;renderWorkoutHistory=function(){oldHistoryRender();$$('#historyList .historyItem').forEach((el,i)=>{const h=workoutHistory[i];const volume=el.querySelectorAll('.historyStat b')[4];if(volume)volume.textContent=rtMassText(h.totalVolume||0);if(h.records?.length){const p=document.createElement('p');p.className='rt-gold';p.textContent='✦ '+h.records.join(' · ');el.append(p)}const details=document.createElement('details'),summary=document.createElement('summary');summary.textContent='Ver series y cargas';details.append(summary);for(const l of h.setLogs||[]){const p=document.createElement('p');p.className='rt-muted';p.textContent=l.name+(l.side?' · '+l.side:'')+' · Serie '+l.set+(l.dropIndex!=null?' · Etapa '+(l.dropIndex+1):'')+' · '+(l.mode==='reps'?(l.reps??'—')+' reps':l.amount+' s')+' · '+rtMassText(l.kg||0);details.append(p)}el.append(details)})};
function rtAchievements(){const sessions=workoutHistory.length,days=new Set(workoutHistory.map(h=>h.localDay||rtDate(new Date(h.finishedAt)))).size,volume=workoutHistory.reduce((n,h)=>n+(h.totalVolume||0),0),streak=RTCore.streak(RT.schedule,workoutHistory,localDate());const weeks={};Object.entries(RT.schedule).forEach(([date,events])=>{if(date>=localDate()||!events.length)return;const d=new Date(date+'T12:00:00');d.setDate(d.getDate()-(d.getDay()+6)%7);(weeks[rtDate(d)]??=[]).push([date,events])});const perfect=Object.entries(weeks).filter(([week,list])=>{const end=new Date(week+'T12:00:00');end.setDate(end.getDate()+6);return rtDate(end)<localDate()&&list.every(([date,events])=>events.every(e=>workoutHistory.some(h=>h.localDay===date&&h.routineId===e.routineId&&h.dayIndex===e.dayIndex))) }).length;const goals=[['Primer entrenamiento',sessions,1],['10 rutinas completadas',sessions,10],['30 días de entrenamiento',days,30],['Volumen registrado: 1.000 kg',volume,1000],['Una semana planificada cumplida',perfect,1],['4 semanas planificadas cumplidas',perfect,4],['Racha de 3 días programados',streak,3]];$('#achievementsSection').innerHTML='<div class="card"><h2>Logros y récords</h2><p class="rt-muted">Son registros de tu constancia, no objetivos para agregar carga o saltarte descansos. Datos de este dispositivo.</p><div class="rt-grid">'+goals.map(([name,n,target])=>`<div class="rt-fieldset"><strong class="${n>=target?'rt-gold':''}">${n>=target?'✦ ':''}${name}</strong><p>${Math.min(target,Math.floor(n))} / ${target}</p><progress class="rt-progress" max="${target}" value="${Math.min(n,target)}"></progress></div>`).join('')+'</div><h3>Mejores cargas registradas</h3><div id="rtRecords"></div></div>';for(const [key,value] of Object.entries(rtRead('records',{}))){const p=document.createElement('p');p.textContent=key.split('|').filter(Boolean).slice(0,2).join(' · ')+' · '+rtMassText(value.kg);$('#rtRecords').append(p)}}
function rtCatalog(){$('#catalogSection').innerHTML='<div class="card rt-pending"><h2>Explorar</h2><p>SECCIÓN EN PROCESO, PRONTO ESTARÁ DISPONIBLE</p></div>'}
async function rtAdmin(){const s=$('#adminSection');s.innerHTML='<div class="card"><h2>Administración</h2><p id="rtAdminStatus">Comprobando permisos…</p><div id="rtAdminTools"></div></div>';if(!navigator.onLine){$('#rtAdminStatus').textContent='Conectate a internet para administrar la app.';return}try{const {data,error}=await db.rpc('rt_is_admin');if(error||data!==true){$('#rtAdminStatus').textContent='El panel está preparado. Falta activar los permisos y la tabla de configuración en Supabase con la migración del repositorio. No se conceden permisos desde el navegador.';return}$('#rtAdminStatus').textContent='Administrador verificado';const result=await db.from('rt_app_config').select('value').eq('id','public').maybeSingle();if(result.error)throw result.error;const config=result.data?.value||{};$('#rtAdminTools').innerHTML='<form id="rtAdminForm"><label>Anuncio de inicio<input id="rtAdminNotice" maxlength="250"></label><label>Diseño global<select id="rtAdminSeason"><option value="auto">Según fecha</option><option value="none">Sin decoración</option><option value="christmas">Navidad</option><option value="newyear">Año nuevo</option><option value="kings">Reyes</option></select></label><button class="primary">Publicar configuración</button></form>';$('#rtAdminNotice').value=config.notice||'';$('#rtAdminSeason').value=config.season||'auto';$('#rtAdminForm').onsubmit=async e=>{e.preventDefault();const {error}=await db.from('rt_app_config').upsert({id:'public',value:{notice:$('#rtAdminNotice').value,season:$('#rtAdminSeason').value}});rtToast(error?'No se pudo guardar: '+error.message:'Configuración publicada')}}catch(e){$('#rtAdminStatus').textContent='No se pudo cargar el panel: '+e.message}}
async function rtPublicConfig(){try{const {data,error}=await db.from('rt_app_config').select('value').eq('id','public').maybeSingle();if(error||!data)return;if(data.value.notice){let p=$('#rtNotice');if(!p){p=document.createElement('p');p.id='rtNotice';$('.header').after(p)}p.textContent=data.value.notice}if((RT.prefs.season||'auto')==='auto'&&data.value.season&&data.value.season!=='auto')document.documentElement.dataset.season=data.value.season}catch{}}
/* Unit preferences change presentation; stored measurements remain kg and cm. */
historyProgressText=function(index){const now=bestLoads(workoutHistory[index]);for(const [name,kg] of Object.entries(now)){for(let i=index+1;i<workoutHistory.length;i++){const old=bestLoads(workoutHistory[i])[name];if(old){if(kg>old)return '+'+rtMassText(kg-old)+' en '+name+' desde el registro anterior';break}}}return ''};
const oldPhysicalRender=renderPhysical;renderPhysical=function(){oldPhysicalRender();$$('#physicalRecords .record').forEach((el,i)=>{const r=[...physicalRecords].reverse()[i];el.querySelector('small').textContent=rtMassText(r.weight)+' · '+rtHeight(r.height).toLocaleString('es-AR',{maximumFractionDigits:2})+' '+(RT.prefs.height||'cm')});const last=physicalRecords.at(-1),prev=physicalRecords.at(-2);if(last&&prev){$('#weightChange').textContent=signed(rtMass(last.weight-prev.weight),RT.prefs.mass||'kg');$('#heightChange').textContent=signed(rtHeight(last.height-prev.height),RT.prefs.height||'cm')}rtUnitLabels()};
const oldSavePhysical=savePhysical;savePhysical=function(){const w=$('#physicalWeight').value,h=$('#physicalHeight').value;$('#physicalWeight').value=rtKg(w);$('#physicalHeight').value=Number(h)*(RT.prefs.height==='m'?100:RT.prefs.height==='in'?2.54:1);oldSavePhysical();$('#physicalWeight').value=w;$('#physicalHeight').value=h};
$('#infoOverlay .infoSteps').insertAdjacentHTML('beforeend','<div class="infoStep"><b>7</b><span>Tocá el ícono de persona para abrir <strong>Mi perfil</strong>, cambiar preferencias y ver tus logros. Los colores están en Inicio.</span></div><div class="infoStep"><b>8</b><span>En <strong>Mis rutinas</strong> creá, editá, buscá e importá. En el calendario, tocá una fecha para planificar o un entrenamiento para moverlo.</span></div><div class="infoStep"><b>9</b><span>En <strong>Cronómetro</strong>, iniciá, marcá vueltas sin detener el tiempo y usá pantalla completa. Durante una rutina también podés ajustar descansos.</span></div><div class="infoStep"><b>10</b><span>Abrí la app con internet para descargarla y guardar tus rutinas antes de usarla sin conexión. Los cambios de rutinas se sincronizan al volver; historial, calendario y favoritos quedan en este dispositivo.</span></div>');
$('#updatesOverlay .updateList').innerHTML=['Calendario más simple: tocá un día para planificar.','Cronómetro con controles ordenados como en entrenamiento.','Cronómetro y vueltas en pantalla completa.','Perfil en el ícono de persona con tus logros.','Los colores ahora están en Inicio.','Crear y editar rutinas desde Mis rutinas.','Tus rutinas y el buscador reunidos en una sola sección.','Explorar queda preparado para las rutinas que llegarán después.'].map(x=>'<li>'+x+'</li>').join('');
showUpdatesOnce=function(){if(!currentUser||!RT.profile.completed||updatesOpened||localStorage.getItem(UPDATES_VERSION)==='seen')return;setTimeout(()=>{if($('#rtDialogOverlay').classList.contains('hidden'))showUpdates(true)},300)};
